-- Supabase-only R3: canonical Kit storage.
-- Server-only tables; Admin access stays behind authenticated Edge Functions.

create table if not exists public.kit_templates (
  id uuid primary key default gen_random_uuid(),
  legacy_id text not null unique,
  sku text not null,
  name text not null,
  description text,
  image_url text,
  price numeric(12,2) not null default 0 check (price >= 0),
  previous_price numeric(12,2) check (previous_price is null or previous_price >= 0),
  discount_percent numeric(7,2) check (discount_percent is null or discount_percent between 0 and 100),
  stock_limit integer check (stock_limit is null or stock_limit >= 0),
  stock_available integer check (stock_available is null or stock_available >= 0),
  starts_on date,
  ends_on date,
  is_active boolean not null default false,
  active_until_stock_zero boolean not null default false,
  metadata jsonb not null default '{}'::jsonb,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id)
);
alter table public.kit_templates enable row level security;
comment on table public.kit_templates is 'Canonical server-only promotional kits. Supabase is the source of truth.';

create table if not exists public.kit_template_items (
  id uuid primary key default gen_random_uuid(),
  kit_id uuid not null references public.kit_templates(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  quantity numeric(12,3) not null check (quantity > 0),
  substitute_product_codes text[] not null default '{}',
  pricing_snapshot jsonb not null default '{}'::jsonb,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(kit_id,product_id)
);
alter table public.kit_template_items enable row level security;
comment on table public.kit_template_items is 'Canonical kit composition linked to public.products.';

create index if not exists kit_templates_active_sort_idx on public.kit_templates(is_active,sort_order,name);
create index if not exists kit_templates_sku_idx on public.kit_templates(sku);
create index if not exists kit_template_items_kit_sort_idx on public.kit_template_items(kit_id,sort_order);
create index if not exists kit_template_items_product_idx on public.kit_template_items(product_id);

insert into public.kit_templates(
 legacy_id,sku,name,description,image_url,price,previous_price,discount_percent,
 stock_limit,stock_available,starts_on,ends_on,is_active,active_until_stock_zero,metadata,sort_order
) values
