), resolved as (
 select i.*,kt.id kit_id,p.id product_id
 from incoming i
 join public.kit_templates kt on kt.legacy_id=i.kit_legacy_id
 join lateral (
   select id from public.products
   where sku=i.product_code or gtin=i.product_code
   order by (sku=i.product_code) desc
   limit 1
 ) p on true
)
insert into public.kit_template_items(kit_id,product_id,quantity,sort_order,pricing_snapshot,substitute_product_codes)
select kit_id,product_id,quantity,sort_order,pricing_snapshot,
       coalesce(array(select jsonb_array_elements_text(coalesce(pricing_snapshot->'substitutos','[]'::jsonb))),'{}'::text[])
from resolved
on conflict (kit_id,product_id) do update set
 quantity=excluded.quantity,
 sort_order=excluded.sort_order,
 pricing_snapshot=excluded.pricing_snapshot,
 substitute_product_codes=excluded.substitute_product_codes,
 updated_at=now();
